import{_ as t,o as s,c as a,a4 as r}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0033 — Captchas tiers : déclarés d'office, exemption appréciée par le site","description":"Extrait de docs/adr/0033-captchas-tiers-declares-d-office.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0033 — Captchas tiers : déclarés d'office, exemption appréciée par le site","description":"Extrait de docs/adr/0033-captchas-tiers-declares-d-office.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0033-captchas-tiers-declares-d-office.md","filePath":"developpeurs/adr/0033-captchas-tiers-declares-d-office.md"}`),i={name:"developpeurs/adr/0033-captchas-tiers-declares-d-office.md"};function n(o,e,c,u,l,d){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0033--captchas-tiers--déclarés-doffice-exemption-appréciée-par-le-site" tabindex="-1">ADR-0033 — Captchas tiers : déclarés d&#39;office, exemption appréciée par le site <a class="header-anchor" href="#adr-0033--captchas-tiers--déclarés-doffice-exemption-appréciée-par-le-site" aria-label="Permalink to &quot;ADR-0033 — Captchas tiers : déclarés d&#39;office, exemption appréciée par le site {#adr-0033--captchas-tiers--déclarés-doffice-exemption-appréciée-par-le-site}&quot;">​</a></h1><p><strong>Date :</strong> 17 septembre 2026 <strong>Statut :</strong> Accepté avec garde-fou <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit de sécurité et RGPD du 15 septembre 2026 (constat « Turnstile et hCaptcha chargent un script tiers hors de tout consentement ») ; directive ePrivacy, art. 5 §3 ; lignes directrices et recommandation « cookies et autres traceurs » de la CNIL ; CDC_CMS_AI_Native_v1.1 §7.1 et §13.3 ; complète l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0015-captcha-non-configure-refus-de-soumission">ADR-0015</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le Core livre trois vérificateurs anti-robot (ADR-0027). Altcha est celui de la pile de développement : il ne contacte personne. <strong>Cloudflare Turnstile</strong> et <strong>hCaptcha</strong>, en revanche, chargent un script de leur éditeur dans le navigateur de chaque usager qui remplit un formulaire.</p><p>Le catalogue des services tiers connaissait des vidéos, des cartes, des outils de mesure d&#39;audience et des réseaux sociaux, mais aucun de ces deux captchas. Une collectivité qui en activait un transmettait donc l&#39;adresse et l&#39;empreinte du navigateur de ses usagers à un tiers, sans que le service apparaisse au gestionnaire de cookies ni au registre des traitements. Notre propre notice demandait pourtant de l&#39;y déclarer, et rien ne permettait de le faire proprement.</p><p>Deux difficultés rendaient la correction moins simple qu&#39;un ajout au catalogue.</p><p><strong>La détection ne pouvait pas le trouver.</strong> Elle lit les compositions de pages ; le captcha, lui, relève d&#39;un réglage de l&#39;installation (<code>CAPTCHA_PROVIDER</code>), pas d&#39;un bloc posé par un rédacteur.</p><p><strong>La question du consentement n&#39;a pas de réponse universelle.</strong> Un traceur strictement nécessaire à un service demandé par l&#39;utilisateur est exempté de consentement. Un captcha protège un formulaire que l&#39;usager veut envoyer, ce qui plaide pour l&#39;exemption. Mais un script tiers qui collecte davantage que ce qu&#39;exige la protection, ou qui sert aussi les finalités de son éditeur, ne l&#39;est pas, et c&#39;est la réserve que la CNIL exprime à l&#39;égard des captchas fournis par des tiers. Pour un service public, il existe une difficulté supplémentaire : soumettre le captcha au consentement revient à fermer les démarches en ligne à quiconque refuse les cookies. Ni l&#39;auteur du CMS ni le catalogue ne peuvent trancher cela pour toutes les collectivités.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Le CMS déclare ces services d&#39;office, les soumet au consentement par défaut, et laisse le DPO de chaque site apprécier l&#39;exemption, par écrit.</strong></p><ol><li><p><strong>Au catalogue.</strong> Cloudflare Turnstile et hCaptcha y figurent, avec leurs hôtes de détection, leur éditeur et leur politique de confidentialité. Leurs cookies ne sont déclarés que lorsque l&#39;éditeur les documente. Ils portent un drapeau que seuls eux ont : <strong>l&#39;exemption y est « à apprécier par le site »</strong>. Pour tout autre service, le catalogue continue de faire foi sur le besoin de consentement : aucun site ne peut déclarer que YouTube n&#39;en exige pas.</p></li><li><p><strong>Proposés d&#39;office.</strong> Quand le captcha actif de l&#39;installation est l&#39;un des deux, l&#39;ordonnanceur inscrit le service au registre des cookies de chaque site, en proposition, comme la détection le fait pour une vidéo. Un changement de captcha impose un redémarrage, et l&#39;ordonnanceur exécute toutes ses tâches dès son démarrage : la proposition apparaît donc sans délai. Tant que le service n&#39;est pas déclaré, le registre des traitements signale un <strong>captcha tiers non déclaré</strong>. Écarter la proposition ne fait pas disparaître ce signalement, car le script, lui, reste chargé.</p></li><li><p><strong>Le DPO tranche, et il motive.</strong> Par défaut, le service est soumis au consentement. Le DPO peut le déclarer <strong>strictement nécessaire</strong> pour son site. Il doit alors écrire un motif, qui est conservé avec son nom et la date. La catégorie suit sa décision, pour que le bandeau et le registre ne se contredisent jamais. Revenir au consentement efface le motif.</p></li></ol><p><strong>Le garde-fou</strong>, qui fait de cette ADR un « Accepté avec garde-fou » : l&#39;exemption n&#39;est possible que pour les services que le catalogue a marqués comme appréciables, et jamais sans motif écrit. La même route refuse aussi désormais un état incohérent qu&#39;elle laissait passer : une catégorie « strictement nécessaire » posée sur un service que le catalogue soumet au consentement.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Toujours soumis au consentement</strong></td><td>La position la plus prudente. Mais un visiteur qui refuse les cookies ne pourrait plus déposer de demande : c&#39;est un mur de consentement sur un service public, pratique que la CNIL n&#39;admet qu&#39;au cas par cas et qui se défend mal quand aucune alternative n&#39;est offerte.</td></tr><tr><td><strong>Toujours strictement nécessaire</strong></td><td>Les formulaires fonctionnent pour tous, mais le CMS trancherait seul, pour toutes les collectivités, une question sur laquelle l&#39;autorité de contrôle appelle à l&#39;examen de chaque service.</td></tr><tr><td><strong>Au catalogue seulement, à déclarer par l&#39;exploitant</strong></td><td>C&#39;est l&#39;oubli que l&#39;audit reprochait. Un service qu&#39;il faut penser à déclarer finit par ne pas l&#39;être.</td></tr><tr><td><strong>Détecter le script dans les pages</strong></td><td>Le script est ajouté par le site public à partir d&#39;un réglage d&#39;installation, pas par une composition de page. La détection ne le verrait que si un rédacteur l&#39;avait collé à la main.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Aucune installation ne peut activer un captcha tiers sans que le service apparaisse au registre des cookies de ses sites et au registre des traitements.</li><li>La décision sur l&#39;exemption est celle du responsable de traitement, écrite et datée, et donc opposable en cas de contrôle.</li></ul><p><strong>Négatives, et il y en a</strong></p><ul><li><strong>Par défaut, un visiteur qui refuse les cookies ne peut pas envoyer de formulaire</strong> tant que le DPO n&#39;a pas statué, si le site applique le bandeau à la lettre. La notice le dit, et recommande Altcha à qui veut éviter la question.</li><li><strong>La liste des cookies dépend de la documentation des éditeurs.</strong> Ce qu&#39;ils ne documentent pas n&#39;y figure pas, et le DPO la complète.</li><li><strong>Le chargement effectif du script est l&#39;affaire du site public</strong>, absent de ce dépôt : le bandeau dit ce qui est permis, et il revient au site de l&#39;appliquer.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Concevoir une alternative pour le visiteur qui refuse les cookies alors que le captcha y est soumis : un second vérificateur, ou un autre canal de dépôt. → <strong>Close le 19/09/2026 par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0036-captcha-sans-consentement-repli-altcha">ADR-0036</a></strong> : repli Altcha, sans cookie ni tiers, proposé d&#39;office à qui n&#39;a pas consenti au captcha tiers.</li></ul>',21)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
